def objs(g,bg):
    seen=[[False]*len(g[0]) for _ in g]; res=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]!=bg and not seen[r][c]:
                st=[(r,c)]; comp=set()
                while st:
                    x,y=st.pop()
                    if (x,y) in comp or seen[x][y]: continue
                    seen[x][y]=True; comp.add((x,y)); col=g[x][y]
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<len(g) and 0<=ny<len(g[0]) and g[nx][ny]==col and not seen[nx][ny]:
                            st.append((nx,ny))
                h=max(x for x,_ in comp)-min(x for x,_ in comp)+1
                w=max(y for _,y in comp)-min(y for _,y in comp)+1
                res.append((col,h*w,comp))
    return res
